import numpy as np
def analyze(inp):
    a=np.array(inp); H,W=a.shape
    sep=None
    for v in np.unique(a):
        if any(all(x==v for x in r) for r in a): sep=int(v); break
    rowg=[r for r in range(H) if all(x==sep for x in a[r])]
    colg=[c for c in range(W) if all(r[c]==sep for r in a)]
    rgp=[]; prev=0
    for r in rowg+[H]:
        if r>prev: rgp.append(list(range(prev,r)))
        prev=r+1
    cgp=[]; prev=0
    for c in colg+[W]:
        if c>prev: cgp.append(list(range(prev,c)))
        prev=c+1
    bg=int(np.bincount(a[a!=sep].ravel().tolist()).argmax())
    def corners(h,w): return {(0,0),(0,w-1),(h-1,0),(h-1,w-1)}
    res=[]
    for rg in rgp:
        line=[]
        for cg in cgp:
            blk=a[np.ix_(rg,cg)]; hh,ww=blk.shape
            m=blk.copy()!=bg
            pts=np.argwhere(m)
            if len(pts)==0: line.append(0); continue
            iscorner=all((int(p[0]),int(p[1])) in corners(hh,ww) for p in pts)
            line.append(2 if iscorner else 1)
        res.append(line)
    return res
