import numpy as np, os, re, json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def patterns(inp):
    a=np.array(inp); H,W=a.shape
    sep=None
    for v in np.unique(a):
        if any(all(x==v for x in r) for r in a): sep=int(v); break
    rowg=[r for r in range(H) if all(x==sep for x in a[r])]
    colg=[c for c in range(W) if all(r[c]==sep for r in a)]
    bg=int(np.bincount(a[a!=sep].ravel().tolist()).argmax())
    def touches(pts,h,w):
        return min(p[0] for p in pts)==0 or min(p[1] for p in pts)==0 or max(p[0] for p in pts)==h-1 or max(p[1] for p in pts)==w-1
    T=[]
    prev_r=0; prev_c=0
    for q in [-1]+rowg+[H]:
        for qq in [-1]+colg+[W]:
            blk=a[np.ix_(range(prev_r,q),range(prev_c,qq))]
            hh,ww=blk.shape
            pts=[(int(p[0]),int(p[1])) for p in np.argwhere(blk!=bg)]
